def is_union_covered(needle_start, needle_end, haystack_sorted):
    """Check [needle_start, needle_end] subset of union(haystack) for integer points."""
    cur = needle_start
    for hs, he in sorted(haystack_sorted):
        if he < cur:
            continue
        if hs > cur:
            return False
        # hs <= cur <= he
        cur = he + 1
        if cur > needle_end:
            return True
    return cur > needle_end

def unions_equal_as_sets(a, b):
    # every interval of a covered by union of b and vice versa
    for s, e in a:
        if not is_union_covered(s, e, b):
            return False
    for s, e in b:
        if not is_union_covered(s, e, a):
            return False
    return True

def reference_merge(intervals):
    items = sorted(intervals)
    if not items:
        return []
    out = []
    cs, ce = items[0]
    for s, e in items[1:]:
        if s <= ce:  # overlap or touch (share a point)
            if e > ce:
                ce = e
        else:
            out.append((cs, ce))
            cs, ce = s, e
    out.append((cs, ce))
    return out

